// CLIPS · game-port (2026-10-27): the few clips of the game's own set (ai-city/game src/anim/clips-game.js, the paused craft game) that
// fit the sim's staging (GAME.md §20; game-port.md: what the city stages for each). slime, 10-27: "b) Port the few that fit the sim's
// staging". Ported as they are in the game, generated by the game's own method (below), with these differences, all of them because the
// port runs on ai-city-fresh main's runtime as it is:
//   · NO AIM. The game reads the player's aim pitch (cAim: a runtime change the game made, walk2.js's look slot) in the head and the
//     swing. The sim has no aim, so `aim` is the constant 0: the pose the game shows when its player looks level.
//   · NO WEAPON. Only the bare-handed versions are ported (the game's `none` hold class: g_punch, g_haymaker*, g_stagger_none,
//     g_pick_up_none, g_drink, g_smoke, the bench loops); no prop: every one of them hides the game's weapon (show 0)
//     and the drink, the joint and the bench's tools were the game's first-person view's. The city draws none (game-port.md).
//   · TIMES ARE CONSTANTS. The game generates each one-shot from its logic/timeline.js ACTIONS (the action's duration and its phases);
//     ACT below is a copy of the entries used (2026-10-27, game 94d1abf). Nothing here imports from the game.
//   · THE WALKING OVERLAY (winded_walk) writes no leg channel (CLIPS.md § Moods and reactions: no P.drop, P.bodyX, P.pRoll), so the
//     legs are the walk's bit for bit. The game's version set the pelvis 2.5 cm lower and zeroed the walk's hip sway and pelvis roll.
//   · moving / speed: the game played its fight and dose clips as overlays (the player walks while punching). The sim stages
//     them standing (`moving: false`): the fight, the drink and the smoke stand. winded_walk is the one overlay (speed 0, stride 1).
//   · THE BENCH LOOPS work at the sim's bench (bench-props.js BENCH: the top at y 0.435), not the game's: their hands are lifted onto
//     a vise on the bench's front edge (BENCH_LIFT, game-port.md § The bench). Unlifted, the game's hands work at y ≈ 0.29, 15 cm
//     inside the sim's bench top.
// THE HANDEDNESS is the game's: its weapon hand is the −x arm (the anatomical right; the game mirrors every track, `mirror` below), so
// the punch, the haymaker, the drink, the smoke and the bench's working hand are the −x arm (the pick-up's is the +x). The sim's own clips use the +x arm.
//
// THE METHOD (the game's clips-game.js, copied): a clip is a TRACK of expressions valid in GLSL (and JS): the chest (tx pitch, ty yaw,
// tz roll, the pelvis drop, the hips' sway bx, the pelvis roll pr), the head (hx, hy: the head's pitch and yaw in the body's frame), a
// weapon pose in the chest frame (x y z, az el rl; here only a place the hands may aim at) and the two hands: each hand is put on its
// target (a point of the weapon `pt`, or a point of the chest's rest frame `at`) by work.js's two-bone IK on the elbow (the reach sets
// the elbow, then the shoulder's turn takes the bent arm's grip onto the target, the elbow toward the pole), blended by k over the
// hand's own `free` angles [pitch, roll, yaw, twist, elbow] (a free hand that `swing`s keeps the walk's swing).
import { keys } from './work.js';
import { viseSetGeometry } from './game-port-props.js';

const f = v => (+v).toFixed(4), PI = Math.PI;
// ── the rig and the reach (work.js: the shoulder, the elbow's hinge, the hand's grip point; the bent arm's reach shell)
const SH = { x: .25, y: .825 }, HINGE = { y: .65, z: .05 }, GRIP = { x: .325, y: .39, z: 0 }, ELB = { y: .65 }, EMAX = 1.45;
const gx = GRIP.x - SH.x, hy = HINGE.y - SH.y, hz = HINGE.z, gy = GRIP.y - HINGE.y, gz = GRIP.z - HINGE.z;
const RA = gx * gx + hy * hy + hz * hz + gy * gy + gz * gz, Bc = 2 * (hy * gy + hz * gz), Bs = 2 * (hy * gz - hz * gy), RB = Math.hypot(Bc, Bs), PHI = Math.atan2(Bs, Bc);
const REACH = { min: Math.sqrt(RA + RB * Math.cos(EMAX - PHI)), max: Math.sqrt(RA + RB) };

// ── THE TIMES (the game's logic/timeline.js ACTIONS @ 94d1abf, the entries these clips use): dur and phases (s), and the events the
// city may time its effects on (a punch's hit, the drink's swallow, the smoke's cloud)
export const ACT = {
  swing:        { dur: .58, phases: { windup: [0, .17], strike: [.17, .27], recover: [.27, .58] }, events: { whoosh: .15, hit: .22 } },
  homerun_wind: { dur: 2.6, phases: { coil: [0, .48], hold: [.48, 2.6] }, events: { full: .48 } },
  homerun:      { dur: .8, phases: { strike: [0, .12], follow: [.12, .38], recover: [.38, .8] }, events: { whoosh: .01, hit: .08 } },
  stagger:      { dur: .9, phases: { rock: [0, .14], wobble: [.14, .62], settle: [.62, .9] }, events: {} },
  winded_rest:  { dur: .75, phases: { inhale: [0, .3], exhale: [.3, .75] }, events: {} },
  winded_walk:  { dur: .75, phases: { inhale: [0, .3], exhale: [.3, .75] }, events: {} },
  pickup:       { dur: .52, phases: { reach: [0, .24], grab: [.24, .3], back: [.3, .52] }, events: { grab: .27 } },
  bench_clamp:  { dur: 1.1, phases: { turn: [0, 1.1] }, events: {} },
  bench_file:   { dur: .85, phases: { push: [0, .45], draw: [.45, .85] }, events: {} },
  bench_fit:    { dur: 1.6, phases: { reach: [0, .55], bring: [.55, 1.15], set: [1.15, 1.6] }, events: {} },
  drink:        { dur: 1.7, phases: { lift: [0, .4], sip: [.4, 1.25], down: [1.25, 1.7] }, events: { dose: 1.1 } },
  smoke:        { dur: 2.4, phases: { lift: [0, .4], drag: [.4, 1.15], away: [1.15, 1.6], exhale: [1.6, 2.1], down: [2.1, 2.4] }, events: { dose: 1.05, exhale: 1.62 } },
};
const ph = (act, p) => ACT[act].phases[p], A = id => ACT[id].dur;

// ── the GLSL body (clips-game.js glslTrack): the chest, the head, then the hands onto their targets. `legs: false` (a walking overlay)
// leaves the pelvis's drop, sway and roll to the walk.
const val = (T, grp, k) => T[grp]?.[k] ?? { tz: '0.', bx: '0.', pr: '0.', rl: '0.', hx: '0.', hy: '0.', drop: '0.' }[k] ?? '0.';
function glslTrack(T, legs = true) {
  const v = (g, k) => val(T, g, k), vec = a => `vec3(${a.join(', ')})`;
  const hand = (h, i) => { const sx = i ? 1 : -1, parts = [], ws = [];
    if (h.pt) { parts.push(`vec3 tP = gkO + gkR * ${vec(h.pt)} - S;`); ws.push(['tP', h.wpt ?? (h.at ? '0.' : '1.')]); }
    if (h.at) { parts.push(`vec3 tA = ${vec(h.at)} - S;`); ws.push(['tA', h.wat ?? '1.']); }
    const W = ws.map(([n, w]) => `float w_${n} = ${w};`).join(' '), sum = ws.map(([n]) => `w_${n}`).join(' + '), mixv = ws.map(([n]) => `${n} * w_${n}`).join(' + ');
    return `{ // the ${i ? '+x' : '−x'} hand
      vec3 S = vec3(${f(sx * SH.x)}, ${f(SH.y)}, 0.), H = ${vec(h.pole)}; float K = ${h.k ?? '1.'};
      ${h.free ? `cArm(P, ${i}, vec4(${h.free.slice(0, 4).join(', ')}), ${h.free[4] ?? '0.'}, ${h.swing ? '1. - w' : '1.'});` : ''}
      ${parts.join('\n      ')}
      ${W} vec3 Tg = (${mixv}) / max(${sum}, 1e-4);
      // the elbow from the reach, then the arm's turn that takes the bent rest arm's grip onto the target, the elbow toward the pole (work.js)
      float r2 = clamp(dot(Tg, Tg), ${f(REACH.min ** 2)}, ${f(REACH.max ** 2)}), we = ${f(PHI)} + acos(clamp((r2 - ${f(RA)}) / ${f(RB)}, -1., 1.)), wc = cos(we), ws = sin(we);
      vec3 wv = vec3(${f(sx * gx)}, ${f(hy)} + wc * ${f(gy)} + ws * ${f(gz)}, ${f(hz)} - ws * ${f(gy)} + wc * ${f(gz)}), wl = vec3(${f(sx * gx)}, ${f(ELB.y - SH.y)}, 0.);
      vec3 e1 = normalize(wv), e2 = normalize(wl - dot(wl, e1) * e1), f1 = normalize(Tg), f2 = normalize(H - dot(H, f1) * f1);
      mat3 wR = mat3(f1, f2, cross(f1, f2)) * transpose(mat3(e1, e2, cross(e1, e2)));
      float wb = asin(clamp(wR[1][2], -1., 1.)), wa = atan(-wR[1][0], wR[1][1]), wcc = atan(-wR[0][2], wR[2][2]);
      if (abs(wa) > 1.5707963) { wa -= sign(wa) * 3.14159265; wb = (wb >= 0. ? 3.14159265 : -3.14159265) - wb; wcc += wcc > 0. ? -3.14159265 : 3.14159265; }
      cArm(P, ${i}, vec4(-wb, ${f(sx)} * wa, 0., ${f(-sx)} * wcc), we, K); }`; };
  return /* glsl */`
  float aim = 0.;   // (the game's aim pitch: level)
  ${(T.vars || []).map(([k, e]) => `float ${k} = ${e};`).join(' ')}
  P.torso = vec3(${v('body', 'tx')}, ${v('body', 'ty')}, ${v('body', 'tz')});${legs ? ` P.drop = ${v('body', 'drop')}; P.pRoll = ${v('body', 'pr')}; P.bodyX = ${v('body', 'bx')};` : ''}
  P.head.x = ${v('head', 'hx')} - P.torso.x; P.head.y = ${v('head', 'hy')} - P.torso.y;
  { mat3 gkR = aRY(${v('gun', 'az')}) * aRX(-(${v('gun', 'el')})) * aRZ(${v('gun', 'rl')}); vec3 gkO = vec3(${v('gun', 'x')}, ${v('gun', 'y')}, ${v('gun', 'z')});
    ${hand(T.hands[0], 0)}
    ${hand(T.hands[1], 1)} }`;
}
// THE HANDEDNESS (clips-game.js mirror): every track is written with the working hand at +x and mirrored: the chest's yaw, roll, sway and
// the pelvis roll, the head's yaw, the weapon's x, yaw and roll are negated, the hands swap and their chest-frame targets and poles are
// reflected (points ON the weapon stay as they are: it is the same object, turned)
const neg = e => `(-(${e}))`, negX = a => a && [neg(a[0]), a[1], a[2]];
function mirror(T) { const M = JSON.parse(JSON.stringify(T));
  for (const k of ['ty', 'tz', 'bx', 'pr']) if (M.body?.[k] !== undefined) M.body[k] = neg(M.body[k]);
  if (M.head?.hy !== undefined) M.head.hy = neg(M.head.hy);
  for (const k of ['x', 'az', 'rl']) if (M.gun?.[k] !== undefined) M.gun[k] = neg(M.gun[k]);
  M.hands = [M.hands[1], M.hands[0]].map(h => ({ ...h, at: negX(h.at), pole: negX(h.pole) }));
  return M; }

// ── THE STANCES and tracks (clips-game.js, the bare-handed ones)
const sw = (n, D) => `sin(${f(2 * PI * n / D)} * t)`;   // a sway term that is 0 at the loop's seams
// the melee hold (the fist down at the side, the handle's place: where a punch and a haymaker start and end; the free arm keeps the
// walk's swing)
const MEL = { tx: .04, ty: .1, drop: .02, x: .36, y: .43, z: .12, az: .25, el: -1.7, rl: 0 };
const MEL_FREE_L = ['.08', '.12', '0.', '.15', '.25'];
// SIM FIX (the sim's hand gate): the empty fist rests FIST_LIFT higher than the game's handle (chest frame), at the hip, out at the side.
// At the game's height the fist came back from the blow through the front of the thigh (punch 0.35–0.5 s, haymaker 0.6–0.75 s).
const FIST_LIFT = .15, FY = MEL.y + FIST_LIFT;
// and the punch's blow ends STRIKE_LIFT higher (at the belly, not the belt), so the fist's way back stays clear of the hip (0.4 s)
const STRIKE_LIFT = .07;
// the haymaker's free arm flares out while the chest is wound round (the coil's chest yaw swung the hanging hand into the thigh, the
// wind at 0.25–0.4 s): roll + FLARE over the coil, held to the release, eased back by its end
const FLARE = .25, flared = env => [{ ...MEL_HANDS[0], free: [MEL_FREE_L[0], `${MEL_FREE_L[1]} + ${f(FLARE)} * ${env}`, ...MEL_FREE_L.slice(2)] }, MEL_HANDS[1]];
const MEL_HANDS = [{ pole: ['-1.', '-.3', '-.3'], k: '0.', free: MEL_FREE_L, swing: 1, at: ['-.3', '.5', '.1'] }, { pt: ['0.', '0.', '0.'], pole: ['1.', '-.6', '-.3'] }];
// the punch (the game's swing with an empty fist): windup (the fist up beside the head, the chest coiled) · strike (across and down as
// the chest unwinds) · recover
const punchTrack = () => { const act = 'swing', W = ph(act, 'windup'), S = ph(act, 'strike'), R = ph(act, 'recover');
  const k3 = (h, w, s) => keys([[0, h], [W[1], w, 'cS'], [S[1], s, 'cOut'], [R[1], h, 'cS']]);
  return { vars: [['st', `cBump(t, ${f(S[0])}, ${f(R[0] + (R[1] - R[0]) * .5)})`]], body: { tx: k3(MEL.tx, -.06, .2), ty: k3(MEL.ty, .6, -.6), drop: k3(MEL.drop, .02, .07) }, head: { hx: `-.4 * aim + .08 * st`, hy: '0.' },
    gun: { x: k3(MEL.x, .58, .18), y: k3(FY, .9, .55 + STRIKE_LIFT), z: k3(MEL.z, .26, .34), az: k3(MEL.az, .9, -.6), el: k3(MEL.el, 1.05, -1.1), rl: k3(0, 0, -.3) }, hands: MEL_HANDS }; };
// THE HAYMAKER (the game's home run with bare hands): the wind (the swing's windup carried on: the fist cocked back behind the head, the
// chest wound right round, the knees bent (coil); held there, trembling (hold)) and the release (whipped flat across the body as the chest
// unwinds past square (strike: the blow), round the far shoulder (follow), back to the hold (recover)). The coil is the release's first
// pose: the wind → release switch at the coil's end (0.48 s) is exact.
const HR_COIL = { tx: -.14, ty: 1.0, drop: .07, x: .5, y: 1.0, z: -.02, az: 1.45, el: 1.2, rl: .35 };
const haymakerWind = () => { const act = 'homerun_wind', C = ph(act, 'coil'), Hd = ph(act, 'hold'), k1 = (h, c) => keys([[0, h], [C[1], c, 'cS']]);
  return { vars: [['tr', `cS(t, ${f(C[1])}, ${f(C[1] + .2)}) * sin(${f(2 * PI * 9)} * t)`], ['hl', `cS(t, ${f(Hd[0])}, ${f(Hd[1])})`]],
    body: { tx: k1(MEL.tx, HR_COIL.tx), ty: `${k1(MEL.ty, HR_COIL.ty)} + .03 * hl`, drop: `${k1(MEL.drop, HR_COIL.drop)} + .004 * tr` }, head: { hx: '-.4 * aim', hy: k1(0, -.35) },
    gun: { x: k1(MEL.x, HR_COIL.x), y: `${k1(FY, HR_COIL.y)} + .006 * tr`, z: k1(MEL.z, HR_COIL.z), az: `${k1(MEL.az, HR_COIL.az)} + .015 * tr`, el: k1(MEL.el, HR_COIL.el), rl: k1(0, HR_COIL.rl) }, hands: flared(`cS(t, 0., ${f(C[1])})`) }; };
const haymakerRelease = () => { const act = 'homerun', S = ph(act, 'strike'), F = ph(act, 'follow'), R = ph(act, 'recover');
  const k4 = (c, s, fo, h) => keys([[0, c], [S[1], s, 'cOut'], [F[1], fo, 'cOut'], [R[1], h, 'cS']]);
  return { vars: [['st', `cBump(t, 0., ${f(F[1])})`]], body: { tx: k4(HR_COIL.tx, .2, .16, MEL.tx), ty: k4(HR_COIL.ty, -.75, -1.0, MEL.ty), drop: k4(HR_COIL.drop, .09, .05, MEL.drop) }, head: { hx: '-.4 * aim + .1 * st', hy: k4(-.35, .2, .3, 0) },
    gun: { x: k4(HR_COIL.x, .12, -.12, MEL.x), y: keys([[0, HR_COIL.y], [S[1], .66, 'cOut'], [F[1], .82, 'cOut'], [F[1] + .6 * (R[1] - F[1]), .8], [R[1], FY]])   /* SIM FIX: held up until the fist is back at the side (the game's crossed the hips at 0.65 s) */, z: k4(HR_COIL.z, .52, .3, MEL.z), az: k4(HR_COIL.az, -1.2, -2.0, MEL.az), el: k4(HR_COIL.el, -.1, .5, MEL.el), rl: k4(HR_COIL.rl, -.25, -.4, 0) }, hands: flared(`(1. - cS(t, ${f(F[1])}, ${f(R[1])}))`) }; };
// the bare stance (clips-game.js pickUp('none')): the body square, both arms free and hanging; the pick-up bends at the knees and the
// waist and takes the (−x before the mirror, +x after) free hand to the ground: reach · grab · back
const pickUp = (act = 'pickup', deep = 1) => { const R = ph(act, 'reach'), B = ph(act, 'back');
  const bend = `cS(t, 0., ${f(R[1])}) * (1. - cS(t, ${f(B[0])}, ${f(B[1])}))`;
  const T = { vars: [], body: { tx: '0.', ty: '0.', drop: '0.' }, head: { hx: '0.', hy: '0.' }, gun: { x: '.3', y: '.5', z: '.2', az: '0.', el: '0.', rl: '0.' },
    hands: [{ pole: ['-1.', '-.3', '-.3'], k: '0.', at: ['-.3', '.5', '.1'], free: ['0.', '.06', '0.', '0.', '0.'] }, { pole: ['1.', '-.3', '-.3'], k: '0.', at: ['.3', '.5', '.1'], free: ['0.', '.06', '0.', '0.', '0.'] }] };
  T.vars = [['bd', bend]]; const b = T.body;
  b.tx = `(${b.tx}) * (1. - bd) + ${f(.62 * deep)} * bd`; b.drop = `(${b.drop}) * (1. - bd) + ${f(.2 * deep)} * bd`; b.ty = `(${b.ty}) * (1. - .5 * bd)`; T.head = { hx: `(${T.head.hx}) * (1. - bd) + .3 * bd`, hy: '0.' };
  T.hands[0] = { ...T.hands[0], k: `(${T.hands[0].k ?? '1.'}) * (1. - bd)`, free: [`mix(.1, ${f(1.3 * (deep < 1 ? .95 : 1))}, bd)`, '.12', 'mix(0., .25, bd)', '.1', 'mix(.25, .1, bd)'] };
  return T; };
// SIM FIX (the sim's hand gate): the reaching hand goes down OUTSIDE the foot (roll + 0.25, no yaw in), and the other arm hangs out of
// the bent thigh (roll + 0.2); the game's reach came down in front of the knee and onto the toes (0.1–0.4 s)
const pickUpSim = () => { const T = pickUp(); T.hands[0].free = [T.hands[0].free[0], '.12 + .25 * bd', '0.', T.hands[0].free[3], T.hands[0].free[4]];
  T.hands[1].free = ['0.', '.06 + .2 * bd', '0.', '0.', '0.']; return T; };
const BARE = () => pickUp();   // the stance the stagger and the doses start from (bd: 0)
// a person staggered by a big blow: rocked back on the heels, the head snapped back (rock) · a wobble (wobble) · back to the stance (settle)
const staggerT = () => { const act = 'stagger', Rk = ph(act, 'rock'), Wb = ph(act, 'wobble'), T = BARE();
  const rk = `(cOut(t, 0., ${f(Rk[1])}) * (1. - cS(t, ${f(Rk[1])}, ${f(Wb[1])})))`, wb = `(sin(${f(2 * PI * 2.2)} * t) * cS(t, ${f(Rk[1])}, ${f(Rk[1] + .1)}) * (1. - cS(t, ${f(Wb[0] + .2)}, ${f(A(act))})))`;
  T.vars = [...T.vars.filter(([k]) => k !== 'bd'), ['bd', '0.'], ['rk', rk], ['wb', wb]];
  T.body = { ...T.body, tx: `(${T.body.tx}) - .42 * rk + .05 * wb`, ty: `(${T.body.ty}) + .3 * rk + .08 * wb`, drop: `(${T.body.drop}) + .1 * rk` }; T.head = { hx: `(${T.head.hx}) - .55 * rk`, hy: `(${T.head.hy ?? '0.'}) + .2 * wb` };
  T.gun = { ...T.gun, y: `(${T.gun.y}) + .08 * rk` };
  // SIM FIX (the sim's hand gate): the arms fling out for balance (roll + 0.35) while it rocks and wobbles; the game's hung at the sides,
  // and the knees, bent by the drop, came up into the hands (0.05–0.35 s)
  T.vars.push(['fl', 'cOut(t, 0., .14) * (1. - cS(t, .45, .9))']); for (const h of T.hands) h.free = h.free.map((e, i) => i === 1 ? `${e} + .35 * fl` : e);
  return T; };
// TAKING A DRINK OR A SMOKE: the hand up under the chin (the toon arm's reach ends there: the big head sits above it) and the head tipped
// back to drink; to smoke, up to the lips for the drag, then out to the side at the shoulder (held in) while the head goes up and the cloud
// comes out (`exhale`: the city's puff)
const doseT = (act) => { const L = ph(act, 'lift'), D = ph(act, 'down'), smoke = act === 'smoke', T = BARE(), lo = `cS(t, 0., ${f(L[1])}) * (1. - cS(t, ${f(D[0])}, ${f(D[1])}))`;
  const aw = smoke ? `cS(t, ${f(ph(act, 'away')[0])}, ${f(ph(act, 'away')[1])})` : '0.', back = smoke ? `(-.12 * cS(t, ${f(ph(act, 'drag')[0])}, ${f(ph(act, 'drag')[1])}) - .22 * cBump(t, ${f(ph(act, 'exhale')[0])}, ${f(ph(act, 'down')[0])}))`
    : `(-.6 * cS(t, ${f(ph(act, 'sip')[0])}, ${f(ph(act, 'sip')[0] + .3)}))`;
  T.vars = [...T.vars.filter(([k]) => k !== 'bd'), ['bd', '0.'], ['lo', lo], ['aw', aw], ['bk', `${back} * lo`]];
  T.gun = { ...T.gun, y: `(${T.gun.y}) - .25 * lo` };
  T.body = { ...T.body, tx: `(${T.body.tx}) * (1. - lo) + .35 * bk`, ty: `(${T.body.ty}) * (1. - lo)` }; T.head = { hx: `(${T.head.hx}) * (1. - lo) + bk`, hy: '0.' };
  const at = (lowV, mouth, out) => `mix(${f(lowV)}, mix(${f(mouth)}, ${f(out)}, aw), lo)`;
  T.hands = [{ pole: ['-1.', '-.3', '-.3'], k: '0.', at: ['-.3', '.5', '.1'], free: ['mix(.1, .2, lo)', '.08', '0.', '0.', '.3'] },
    { pole: ['1.', '-.7', '-.1'], k: '1.', at: [at(.3, .06, .4), at(.5, .9, .72), at(.18, .42, .26)] }];
  return T; };
// WINDED: a quick inhale lifts the shoulders, a longer exhale lets them sag. At rest the palms brace above the knees; walking the hands hang
// slack (the walk's legs)
// SIM FIX (the sim's hand gate, which fails any hand ON a leg: CLIPS.md § What the arm can't do): at rest the hands hang just clear in
// front of the knees (the game braced them on the knees, chest frame (±0.16, 0.46, 0.18)); walking, the slack arms hang a little further
// out (roll 0.1 → WALK_ROLL), clear of the swinging thighs
const WIND_AT = [.22, .71, .41], WALK_ROLL = .22;
const windedTrack = rest => {
  const act = rest ? 'winded_rest' : 'winded_walk', I = ph(act, 'inhale'), E = ph(act, 'exhale');
  return { vars: [['br', `cS(t, ${f(I[0])}, ${f(I[1])}) * (1. - cS(t, ${f(E[0])}, ${f(E[1])}))`]],
    body: { tx: rest ? '.55 + .065 * br' : '.16 + .05 * br', ty: '0.', drop: rest ? '.10 - .018 * br' : '.025 - .012 * br' },
    head: { hx: rest ? '.65 + .025 * br' : '.2 + .025 * br', hy: '0.' },
    gun: { x: '.3', y: '.4', z: '.1', az: '0.', el: '0.' },
    hands: [-1, 1].map(s => ({ at: rest ? [f(s * WIND_AT[0]), f(WIND_AT[1]), f(WIND_AT[2])] : [f(s * .16), '.46', '.18'], pole: [f(s), '-.4', '-.2'], k: rest ? '1.' : '0.', free: ['.12 + .04 * br', rest ? '.1' : f(WALK_ROLL), '0.', '.1', '.15'] })) };
};
// THE BENCH (the game's Gun Bench loops): the chest bent over the work, the head down
//   clamp: the working hand cranks the vise's T-bar round in front at the bench's edge (a turn a cycle), the other hand steadies the blank
//   file:  both hands on the file at the vise, pushed across and drawn back, the chest leaning into each push
//   fit:   the working hand reaches out to the side over the bench for a part, brings it back to the gun in the vise and sets it
// BENCH_LIFT (m, the chest's rest frame, up): the sim's bench top is at y 0.435 (bench-props.js BENCH), so the hands are lifted from the
// game's places (body y ≈ 0.29) to work at the jaws of a vise on its front edge (body y ≈ 0.45–0.62, game-port.md § The bench)
const BENCH_LIFT = .25;
const benchTrack = (act) => { const D = A(act), w = f(2 * PI / D), FREE = ['.1', '.12', '0.', '.15', '.25'], up = y => `${y} + ${f(BENCH_LIFT)}`;
  const base = { body: { tx: '.24', ty: '.08', drop: '.05' }, head: { hx: '.5', hy: '0.' }, gun: { x: '.3', y: '.5', z: '.2', az: '0.', el: '0.', rl: '0.' } };
  if (act === 'bench_clamp') return { ...base, vars: [['ca', `cos(${w} * t)`], ['sa', `sin(${w} * t)`]],
    hands: [{ at: ['-.05', up('.46'), '.36'], pole: ['-1.', '-.4', '-.3'], free: FREE }, { at: ['.13 + .09 * ca', up('.43 + .09 * sa'), '.42'], pole: ['1.', '-.3', '-.4'], free: FREE }] };
  if (act === 'bench_file') return { ...base, vars: [['s', `.5 - .5 * cos(${w} * t)`]], body: { tx: '.26 + .06 * s', ty: '.06', drop: '.05 + .01 * s' },
    hands: [{ at: ['-.02', up('.47'), '.44 + .12 * s'], pole: ['-1.', '-.4', '-.3'], free: FREE }, { at: ['.09', up('.46'), '.3 + .12 * s'], pole: ['1.', '-.3', '-.4'], free: FREE }] };
  return { ...base, vars: [['r', `cS(t, 0., ${f(D * .34)}) * (1. - cS(t, ${f(D * .4)}, ${f(D * .72)}))`], ['dn', `cBump(t, ${f(D * .72)}, ${f(D * .95)})`]], body: { tx: '.2 + .06 * r', ty: '.08 - .3 * r', drop: '.05' }, head: { hx: '.45', hy: '-.3 * r' },
    hands: [{ at: ['-.06', up('.45'), '.38'], pole: ['-1.', '-.4', '-.3'], free: FREE }, { at: ['.14 + .2 * r', up('.47 - .03 * r - .03 * dn'), '.36 + .06 * r'], pole: ['1.', '-.3', '-.4'], free: FREE }] }; };

// ── the entries (CLIPS.md § The entry). `game`: the game's clip it was ported from. Beats (s, the clip clock) for the city's effects.
const clip = (o) => { const T = mirror(o.track), moving = !!o.moving;
  return { name: o.name, dur: o.dur, loop: !!o.loop, hold: !!o.hold, next: o.next || null, blendIn: o.blendIn ?? .12, blendOut: o.blendOut ?? .25, moving, speed: 0, stride: 1,
    pair: o.pair || null, game: o.game, ...(o.beats || {}), ...(o.set ? { set: o.set } : {}), note: o.note, glsl: glslTrack(T, !moving) }; };
// the lab's stand-in bench with its vise (game-port-props.js; lab only, as bench.js's SET)
